const MONTHS={январь:1,февраль:2,март:3,апрель:4,май:5,июнь:6,июль:7,август:8,сентябрь:9,октябрь:10,ноябрь:11,декабрь:12};
const MONTH_NAMES=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
const SHEET_RE=/^(Январь|Февраль|Март|Апрель|Май|Июнь|Июль|Август|Сентябрь|Октябрь|Ноябрь|Декабрь)\s+(\d{4})$/i;
const LABEL_RE=/^\s*(Время|Адрес|Тел\.?\s*Заказчика|Телефон\s*Заказчика|Вид\s*услуги|Общая\s*сумма|Оплата|Статус|Исполнитель|Примечание)\s*:\s*(.*)$/i;
const PHONE_RE=/(?:\+?7|8)[\s\-()]*\d(?:[\s\-()]*\d){9}/g;
const CRM_ORDERS='CRM_Заказы';
const CRM_CHANGES='CRM_Изменения';
const CRM_SUBS='CRM_Абонементы';
const CRM_LOG='CRM_Журнал';
const ORDER_HEAD=['ID','Дата','Время','Клиент','Телефон','Адрес','Услуга','Сумма','Оплата','Статус','Исполнитель','Примечание','Создал','Создано','Изменено'];
const CHANGE_HEAD=['OrderID','JSON','Изменил','Изменено'];
const SUB_HEAD=['ID','Клиент','Телефон','Пакет','Всего уборок','Использовано','Дата начала','Дата окончания','Сумма','Статус','Примечание','Создано','Изменено'];
const LOG_HEAD=['Дата','Пользователь','Действие','Объект','ID','Подробности'];
const enc=new TextEncoder();
let tokenCache={token:'',exp:0};
let dataCache={at:0,key:'',payload:null};

const J=(x,s=200)=>new Response(JSON.stringify(x),{status:s,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const IDSET=v=>new Set(String(v||'').split(',').map(x=>Number(x.trim())).filter(Number.isFinite));
const escSheet=s=>`'${String(s).replace(/'/g,"''")}'`;
const isoNow=()=>new Date().toISOString();

function hex(b){return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function hmac(k,m){const key=await crypto.subtle.importKey('raw',k,{name:'HMAC',hash:'SHA-256'},false,['sign']);return crypto.subtle.sign('HMAC',key,enc.encode(m))}
async function auth(req,env){
  const d=req.headers.get('X-Telegram-Init-Data')||'';
  if(!d)throw Object.assign(new Error('Откройте приложение из Telegram'),{status:401});
  const p=new URLSearchParams(d),h=p.get('hash');
  if(!h)throw Object.assign(new Error('Нет подписи Telegram'),{status:401});
  p.delete('hash');
  const check=[...p.keys()].sort().map(k=>`${k}=${p.get(k)}`).join('\n');
  const secret=await hmac(enc.encode('WebAppData'),env.BOT_TOKEN);
  const calc=hex(await hmac(new Uint8Array(secret),check));
  if(calc!==h.toLowerCase())throw Object.assign(new Error('Неверная подпись Telegram'),{status:401});
  let u={};try{u=JSON.parse(p.get('user')||'{}')}catch{}
  const id=Number(u.id||0),admins=IDSET(env.ALLOWED_TELEGRAM_IDS),accountants=IDSET(env.ACCOUNTANT_TELEGRAM_IDS);
  if(!admins.has(id)&&!accountants.has(id))throw Object.assign(new Error('Доступ запрещён'),{status:403});
  return{id,name:[u.first_name,u.last_name].filter(Boolean).join(' ')||u.username||String(id),role:admins.has(id)?'admin':'accountant'};
}

function pem(p){const b=p.replace(/-----BEGIN PRIVATE KEY-----|-----END PRIVATE KEY-----|\s+/g,'');const x=atob(b);return Uint8Array.from(x,c=>c.charCodeAt(0)).buffer}
function b64u(a){let s='';for(const b of(a instanceof Uint8Array?a:new Uint8Array(a)))s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
async function googleToken(env){
  if(tokenCache.token&&tokenCache.exp>Date.now()+60000)return tokenCache.token;
  let sa;try{sa=JSON.parse(env.GOOGLE_SERVICE_ACCOUNT_JSON)}catch{throw new Error('Ошибка JSON сервисного аккаунта Google')}
  const now=Math.floor(Date.now()/1000),header=b64u(enc.encode(JSON.stringify({alg:'RS256',typ:'JWT'}))),payload=b64u(enc.encode(JSON.stringify({iss:sa.client_email,scope:'https://www.googleapis.com/auth/spreadsheets',aud:sa.token_uri||'https://oauth2.googleapis.com/token',iat:now,exp:now+3600}))),unsigned=`${header}.${payload}`;
  const key=await crypto.subtle.importKey('pkcs8',pem(sa.private_key),{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['sign']);
  const sig=await crypto.subtle.sign('RSASSA-PKCS1-v1_5',key,enc.encode(unsigned));
  const r=await fetch(sa.token_uri||'https://oauth2.googleapis.com/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'urn:ietf:params:oauth:grant-type:jwt-bearer',assertion:`${unsigned}.${b64u(sig)}`})});
  const x=await r.json();
  if(!r.ok||!x.access_token)throw new Error(`Google OAuth: ${x.error_description||x.error||r.status}`);
  tokenCache={token:x.access_token,exp:Date.now()+Number(x.expires_in||3600)*1000};return x.access_token;
}
async function gf(env,path,opt={}){
  const t=await googleToken(env);
  const r=await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${env.GOOGLE_SHEET_ID}${path}`,{...opt,headers:{authorization:`Bearer ${t}`,'content-type':'application/json',...(opt.headers||{})}});
  const x=await r.json().catch(()=>({}));
  if(!r.ok)throw new Error(`Google Sheets: ${x?.error?.message||r.status}`);return x;
}
async function metadata(env){return gf(env,'?fields=sheets.properties(title,index,sheetId)')}
async function sheetNames(env){const x=await metadata(env);return(x.sheets||[]).sort((a,b)=>(a.properties.index||0)-(b.properties.index||0)).map(x=>x.properties.title)}
async function ensureSheet(env,title,head){
  const m=await metadata(env),exists=(m.sheets||[]).some(s=>s.properties.title===title);
  if(!exists){await gf(env,':batchUpdate',{method:'POST',body:JSON.stringify({requests:[{addSheet:{properties:{title}}}]})});}
  const r=await gf(env,`/values/${encodeURIComponent(`${escSheet(title)}!1:1`)}?valueRenderOption=FORMATTED_VALUE`);
  if(!(r.values||[]).length)await gf(env,`/values/${encodeURIComponent(`${escSheet(title)}!A1:${String.fromCharCode(64+head.length)}1`)}?valueInputOption=RAW`,{method:'PUT',body:JSON.stringify({values:[head]})});
}
async function ensureCRM(env){
  await ensureSheet(env,CRM_ORDERS,ORDER_HEAD);
  await ensureSheet(env,CRM_CHANGES,CHANGE_HEAD);
  await ensureSheet(env,CRM_SUBS,SUB_HEAD);
  await ensureSheet(env,CRM_LOG,LOG_HEAD);
}
async function appendRow(env,title,values){return gf(env,`/values/${encodeURIComponent(`${escSheet(title)}!A:Z`)}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,{method:'POST',body:JSON.stringify({values:[values]})})}
async function putRow(env,title,row,values,lastCol='Z'){return gf(env,`/values/${encodeURIComponent(`${escSheet(title)}!A${row}:${lastCol}${row}`)}?valueInputOption=USER_ENTERED`,{method:'PUT',body:JSON.stringify({values:[values]})})}
async function logAction(env,user,action,obj,id,details=''){try{await appendRow(env,CRM_LOG,[isoNow(),user.name,action,obj,id,details])}catch(e){console.error('log',e)}}

function parts(n){const m=String(n).trim().match(SHEET_RE);return m?[MONTHS[m[1].toLowerCase()],Number(m[2])]:null}
function excelDay(n){return new Date(Date.UTC(1899,11,30)+Number(n)*86400000).getUTCDate()}
function headerDate(v,m,y){
  let d=null;
  if(typeof v==='number'&&v>10000)d=excelDay(v);
  else if(typeof v==='string'){
    const s=v.trim();let q;
    if((q=s.match(/^(\d{1,2})[./](\d{1,2})[./](\d{2,4})$/)))d=+q[1];
    else if((q=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/)))d=+q[3];
    else if(/^\d{1,2}$/.test(s))d=+s;
  }
  if(!d)return null;const z=new Date(Date.UTC(y,m-1,d));if(z.getUTCMonth()!==m-1)return null;
  return`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}
function dateCols(name,vals){const [m,y]=parts(name)||[],out=new Map();if(!m)return out;const h=vals[1]||[];let cur=null;for(let c=1;c<=Math.max(h.length,...vals.map(r=>r.length));c++){const d=headerDate(h[c-1],m,y);if(d)cur=d;if(cur)out.set(c,cur)}return out}
function label(s){s=s.replace(/\s+/g,' ').trim().toLowerCase();if(s==='время')return'time';if(s==='адрес')return'address';if(s.includes('заказчика'))return'contact';if(s==='вид услуги')return'service';if(s==='общая сумма')return'amount';if(s==='оплата')return'payment';if(s==='статус')return'status';if(s==='исполнитель')return'cleaner';if(s==='примечание')return'comment'}
function contact(v){const raw=String(v||'').replace(/\s+/g,' ').trim(),ms=[...raw.matchAll(PHONE_RE)],phones=ms.map(m=>m[0].trim());let client=raw;for(let i=ms.length-1;i>=0;i--){const m=ms[i];client=client.slice(0,m.index)+' '+client.slice(m.index+m[0].length)}client=client.replace(/\s+/g,' ').replace(/^[\s,;\-/]+|[\s,;\-/]+$/g,'');return[client,phones.join(', ')]}
function parseCell(text,date,sheet,row,col){
  const raw=String(text||'').trim(),low=raw.toLowerCase();
  if(!raw||!['адрес:','заказчика:','вид услуги:','общая сумма:'].some(x=>low.includes(x)))return null;
  const f={};let cur=null;
  for(const line of raw.split(/\r?\n/)){const m=line.match(LABEL_RE);if(m){cur=label(m[1]);if(cur)f[cur]=m[2].trim()}else if(cur&&line.trim())f[cur]=`${f[cur]||''}\n${line.trim()}`.trim()}
  if(!f.address&&!f.contact&&!f.service&&!f.amount)return null;
  const [client,phone]=contact(f.contact);
  return{id:`legacy:${sheet}:${row}:${col}`,source:'legacy',date,time:f.time||'',client,phone,address:f.address||'',service:f.service||'',amount:f.amount||'',payment:f.payment||'',status:f.status||'',cleaner:f.cleaner||'',comment:f.comment||'',legacy_sheet:sheet};
}
async function legacyOrders(env){
  const names=(await sheetNames(env)).filter(parts);if(!names.length)return[];
  const q=new URLSearchParams({valueRenderOption:'UNFORMATTED_VALUE',dateTimeRenderOption:'SERIAL_NUMBER'});for(const n of names)q.append('ranges',`${escSheet(n)}!1:31`);
  const x=await gf(env,`/values:batchGet?${q}`),out=[];
  for(let i=0;i<names.length;i++){
    const name=names[i],v=x.valueRanges?.[i]?.values||[],dc=dateCols(name,v);
    for(let r=3;r<=v.length;r++){const row=v[r-1]||[];for(let c=2;c<=row.length;c++){const d=dc.get(c),cell=row[c-1];if(d&&typeof cell==='string'){const o=parseCell(cell,d,name,r,c);if(o)out.push(o)}}}
  }
  return out;
}
async function crmOrders(env){
  await ensureCRM(env);const x=await gf(env,`/values/${encodeURIComponent(`${escSheet(CRM_ORDERS)}!A2:O`)}?valueRenderOption=FORMATTED_VALUE`);
  return(x.values||[]).filter(r=>r[0]).map((r,i)=>({id:r[0],source:'crm',row:i+2,date:r[1]||'',time:r[2]||'',client:r[3]||'',phone:r[4]||'',address:r[5]||'',service:r[6]||'',amount:r[7]||'',payment:r[8]||'',status:r[9]||'',cleaner:r[10]||'',comment:r[11]||'',created_by:r[12]||'',created_at:r[13]||'',updated_at:r[14]||''}));
}
async function changes(env){
  await ensureCRM(env);const x=await gf(env,`/values/${encodeURIComponent(`${escSheet(CRM_CHANGES)}!A2:D`)}?valueRenderOption=FORMATTED_VALUE`),m=new Map();
  (x.values||[]).forEach((r,i)=>{if(!r[0])return;let patch={};try{patch=JSON.parse(r[1]||'{}')}catch{}m.set(r[0],{row:i+2,patch,user:r[2]||'',updated:r[3]||''})});return m;
}
async function subscriptions(env){
  await ensureCRM(env);const x=await gf(env,`/values/${encodeURIComponent(`${escSheet(CRM_SUBS)}!A2:M`)}?valueRenderOption=FORMATTED_VALUE`);
  return(x.values||[]).filter(r=>r[0]).map((r,i)=>({id:r[0],row:i+2,client:r[1]||'',phone:r[2]||'',plan:r[3]||'',total:Number(r[4]||0),used:Number(r[5]||0),start:r[6]||'',end:r[7]||'',amount:r[8]||'',status:r[9]||'Активен',note:r[10]||'',created_at:r[11]||'',updated_at:r[12]||''}));
}
async function allOrders(env){
  const [legacy,crm,chg]=await Promise.all([legacyOrders(env),crmOrders(env),changes(env)]);let all=[...legacy,...crm];
  all=all.map(o=>{const c=chg.get(o.id);return c?{...o,...c.patch,change_meta:{by:c.user,at:c.updated}}:o}).filter(o=>o.status!=='Удалён');
  all.sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.time).localeCompare(String(b.time)));return all;
}
function num(v){const s=String(v??'').toLowerCase().replace(/₽|руб\.?/g,'').trim();if(!/^[0-9\s.,-]+$/.test(s))return 0;const n=Number(s.replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)?n:0}
function normPhone(v){return String(v||'').replace(/\D/g,'').replace(/^8(?=\d{10}$)/,'7')}
function today(env){return new Intl.DateTimeFormat('en-CA',{timeZone:env.APP_TIMEZONE||'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function add(iso,n){const d=new Date(`${iso}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function nowLocal(env){const d=new Date(),parts=new Intl.DateTimeFormat('en-CA',{timeZone:env.APP_TIMEZONE||'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(d).reduce((a,p)=>(a[p.type]=p.value,a),{});return{date:`${parts.year}-${parts.month}-${parts.day}`,time:`${parts.hour}:${parts.minute}`}}
function isDebt(o){const p=String(o.payment||'').toLowerCase();return['не оплачено','не оплачен','долг','частично'].some(x=>p.includes(x))}
function isDone(o){return String(o.status||'').toLowerCase().includes('выполн')}
function isCanceled(o){return String(o.status||'').toLowerCase().includes('отмен')}
function isConfirmed(o){return String(o.status||'').toLowerCase().includes('подтверж')}
function orderClients(all,subs,t){
  const m=new Map();for(const o of all){const k=normPhone(o.phone)||String(o.client||'').toLowerCase().trim();if(!k)continue;const c=m.get(k)||{key:k,client:o.client||'Без имени',phone:o.phone||'',orders:0,total:0,last:'',next:'',addresses:[],services:[],debt:0};c.orders++;c.total+=num(o.amount);if(isDebt(o))c.debt+=num(o.amount);if(o.date&&(!c.last||o.date>c.last)&&o.date<t)c.last=o.date;if(o.date>=t&&(!c.next||o.date<c.next))c.next=o.date;if(o.address&&!c.addresses.includes(o.address))c.addresses.push(o.address);if(o.service&&!c.services.includes(o.service))c.services.push(o.service);m.set(k,c)}
  for(const s of subs){const k=normPhone(s.phone)||String(s.client||'').toLowerCase().trim(),c=m.get(k)||{key:k,client:s.client||'Без имени',phone:s.phone||'',orders:0,total:0,last:'',next:'',addresses:[],services:[],debt:0};c.subscription=s;m.set(k,c)}
  return[...m.values()].sort((a,b)=>{if(a.next&&!b.next)return-1;if(!a.next&&b.next)return 1;return b.orders-a.orders});
}
function buildDashboard(env,user,all,subs){
  const t=today(env),tm=add(t,1),weekEnd=add(t,6),month=t.slice(0,7),local=nowLocal(env),future=all.filter(o=>o.date>=t&&!isCanceled(o)),monthOrders=all.filter(o=>o.date.startsWith(month)&&!isCanceled(o)),debt=all.filter(o=>isDebt(o)&&!isCanceled(o));
  const next=future.find(o=>o.date>local.date||(o.date===local.date&&(!o.time||o.time>=local.time)))||future[0]||null;
  const attention=[];
  const noCleaner=future.filter(o=>!String(o.cleaner||'').trim()).slice(0,20);if(noCleaner.length)attention.push({type:'cleaner',severity:noCleaner.some(o=>o.date===t)?'high':'medium',count:noCleaner.length,title:'Без исполнителя',subtitle:`${noCleaner.length} заказов требуют назначения`});
  const unconfirmed=future.filter(o=>!isConfirmed(o)&&!isDone(o)).slice(0,20);if(unconfirmed.length)attention.push({type:'confirm',severity:'medium',count:unconfirmed.length,title:'Не подтверждены',subtitle:`${unconfirmed.length} будущих заказов`});
  if(debt.length)attention.push({type:'debt',severity:'high',count:debt.length,title:'Есть задолженность',subtitle:`${debt.reduce((s,o)=>s+num(o.amount),0).toLocaleString('ru-RU')} ₽`});
  for(const s of subs.filter(s=>String(s.status).toLowerCase()==='активен')){const left=Math.max(0,s.total-s.used);if(left<=2)attention.push({type:'subscription',severity:left<=1?'high':'medium',count:left,title:left===0?'Абонемент закончился':`Осталось ${left} уборок`,subtitle:s.client||s.phone,subscription_id:s.id});else if(s.end&&s.end<=add(t,7))attention.push({type:'subscription',severity:'medium',count:left,title:'Абонемент скоро закончится',subtitle:s.client||s.phone,subscription_id:s.id})}
  const cleaners=new Map();for(const o of all.filter(o=>o.date===t&&!isCanceled(o))){const name=String(o.cleaner||'').trim();if(!name)continue;const x=cleaners.get(name)||{name,orders:0,amount:0};x.orders++;x.amount+=num(o.amount);cleaners.set(name,x)}
  return{today:t,me:user,dashboard:{today:all.filter(o=>o.date===t&&!isCanceled(o)).length,tomorrow:all.filter(o=>o.date===tm&&!isCanceled(o)).length,week:all.filter(o=>o.date>=t&&o.date<=weekEnd&&!isCanceled(o)).length,month:monthOrders.length,revenue_month:monthOrders.reduce((s,o)=>s+num(o.amount),0),paid_month:monthOrders.filter(o=>!isDebt(o)).reduce((s,o)=>s+num(o.amount),0),unpaid_count:debt.length,unpaid_amount:debt.reduce((s,o)=>s+num(o.amount),0),next,attention,active_subscriptions:subs.filter(s=>String(s.status).toLowerCase()==='активен').length,cleaners:[...cleaners.values()]},orders:all,subscriptions:subs,clients:orderClients(all,subs,t)};
}
async function bootstrap(env,user,force=false){
  const key=`${env.GOOGLE_SHEET_ID}:${today(env)}`;
  if(!force&&dataCache.payload&&dataCache.key===key&&Date.now()-dataCache.at<20000)return{...dataCache.payload,me:user};
  await ensureCRM(env);const [all,subs]=await Promise.all([allOrders(env),subscriptions(env)]);const payload=buildDashboard(env,user,all,subs);dataCache={at:Date.now(),key,payload};return payload;
}
function clearCache(){dataCache={at:0,key:'',payload:null}}

async function createOrder(env,user,p){
  await ensureCRM(env);if(user.role==='accountant')throw Object.assign(new Error('Бухгалтер не может создавать заказы'),{status:403});
  const id=`crm-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,now=isoNow(),row=[id,p.date||'',p.time||'',p.client||'',p.phone||'',p.address||'',p.service||'',p.amount||'',p.payment||'Не оплачено',p.status||'Новый',p.cleaner||'',p.comment||'',user.name,now,now];
  await appendRow(env,CRM_ORDERS,row);await logAction(env,user,'Создан заказ','Заказ',id,`${p.date||''} ${p.client||''}`);clearCache();return{id};
}
async function saveChange(env,user,id,patch,action='Изменён заказ'){
  await ensureCRM(env);if(user.role==='accountant'){
    const allowed=['payment','status','comment'];if(Object.keys(patch).some(k=>!allowed.includes(k)))throw Object.assign(new Error('Бухгалтер может менять только оплату, статус и комментарий'),{status:403});
  }
  const m=await changes(env),now=isoNow(),existing=m.get(id),merged={...(existing?.patch||{}),...patch};
  if(existing)await putRow(env,CRM_CHANGES,existing.row,[id,JSON.stringify(merged),user.name,now],'D');else await appendRow(env,CRM_CHANGES,[id,JSON.stringify(merged),user.name,now]);
  await logAction(env,user,action,'Заказ',id,JSON.stringify(patch));clearCache();return{id};
}
async function createSubscription(env,user,p){
  await ensureCRM(env);if(user.role==='accountant')throw Object.assign(new Error('Бухгалтер не может создавать абонементы'),{status:403});
  const id=`sub-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,now=isoNow(),row=[id,p.client||'',p.phone||'',p.plan||'',Number(p.total||0),Number(p.used||0),p.start||today(env),p.end||'',p.amount||'',p.status||'Активен',p.note||'',now,now];
  await appendRow(env,CRM_SUBS,row);await logAction(env,user,'Создан абонемент','Абонемент',id,`${p.client||''} ${p.total||0}`);clearCache();return{id};
}
async function updateSubscription(env,user,id,patch){
  await ensureCRM(env);const list=await subscriptions(env),s=list.find(x=>x.id===id);if(!s)throw Object.assign(new Error('Абонемент не найден'),{status:404});
  if(user.role==='accountant'&&Object.keys(patch).some(k=>!['used','status','note'].includes(k)))throw Object.assign(new Error('Недостаточно прав'),{status:403});
  const n={...s,...patch,updated_at:isoNow()};await putRow(env,CRM_SUBS,s.row,[n.id,n.client,n.phone,n.plan,Number(n.total||0),Number(n.used||0),n.start,n.end,n.amount,n.status,n.note,n.created_at||isoNow(),n.updated_at],'M');await logAction(env,user,'Изменён абонемент','Абонемент',id,JSON.stringify(patch));clearCache();return{id};
}
async function useSubscription(env,user,id){const list=await subscriptions(env),s=list.find(x=>x.id===id);if(!s)throw Object.assign(new Error('Абонемент не найден'),{status:404});if(s.used>=s.total)throw Object.assign(new Error('Все уборки уже использованы'),{status:400});return updateSubscription(env,user,id,{used:s.used+1,status:s.used+1>=s.total?'Завершён':'Активен'});}

async function tg(env,method,payload){const r=await fetch(`https://api.telegram.org/bot${env.BOT_TOKEN}/${method}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const x=await r.json();if(!x.ok)throw new Error(x.description||'Telegram error');return x}
async function ensureBot(env,origin){
  if(!env.BOT_TOKEN)return;
  const webhook=`${origin}/telegram/webhook`;try{const i=await tg(env,'getWebhookInfo',{});if(i?.result?.url!==webhook)await tg(env,'setWebhook',{url:webhook,...(env.TELEGRAM_WEBHOOK_SECRET?{secret_token:env.TELEGRAM_WEBHOOK_SECRET}:{}),allowed_updates:['message']});}catch(e){console.error('webhook',e)}
  try{await tg(env,'setMyName',{name:'House Cleaning'});await tg(env,'setMyShortDescription',{short_description:'Управление заказами, клиентами и клинингом'});await tg(env,'setMyDescription',{description:'House Cleaning — график заказов, клиенты, абонементы, финансы и команда.'});}catch(e){console.error('bot profile',e)}
}
async function telegramHook(req,env){
  if(env.TELEGRAM_WEBHOOK_SECRET&&req.headers.get('X-Telegram-Bot-Api-Secret-Token')!==env.TELEGRAM_WEBHOOK_SECRET)return J({ok:false},403);
  const u=await req.json(),m=u.message;if(!m)return J({ok:true});const id=Number(m.from?.id),chat=m.chat?.id,admins=IDSET(env.ALLOWED_TELEGRAM_IDS),accountants=IDSET(env.ACCOUNTANT_TELEGRAM_IDS);
  if(String(m.text||'').startsWith('/start')){if(!admins.has(id)&&!accountants.has(id))await tg(env,'sendMessage',{chat_id:chat,text:'Доступ закрыт.'});else await tg(env,'sendMessage',{chat_id:chat,text:'House Cleaning\n\nПанель управления клинингом.',reply_markup:{inline_keyboard:[[{text:'Открыть приложение',web_app:{url:new URL(req.url).origin}}]]}})}return J({ok:true});
}

